@startuml

class Center {
  + name : string
  + address : string
}

class Room {
  + roomNumber : int
  + maxCapacity : int
}

class Person {
  + firstName : string
  + familyName : string
  + birthDate : date
}

class Trainer {
  + diploma : string
}

class Member {
}

class Session {
  + date : date
  + startHour : time
}

class IndividualSession {
}

class GroupSession {
  + type : string
}

Center "1" *-- "1..*" Room
Room "1" -- "0..1" Session
Person --|> Trainer
Person --|> Member

Trainer "1" -- "0..*" GroupSession : supervises
Person "1" -- "0..*" Session : participates

GroupSession --|> Session
IndividualSession --|> Session

@enduml

